For homomorphisms and line bundles as indicated,
\begin{enumerate}
\item $e^{f^*L}(x,y)=e^L(fx,fy)$;
\item $e^{L_1\otimes L_2}(x,y)=e^{L_1}(x,y)e^{L_2}(x,y)$;
\item algebraically equivalent line bundles have equal pairings;
\item $e^{L^n}(x,y)=e^L(x,ny)$ for $x\in K(L)$,
$y\in n_X^{-1}K(L)$;
\item if $x\in X_n$ and $y\in\phi_L^{-1}(X_n)$, then
$\bar e_n(x,\phi_L(y))=e^{L^n}(x,y)$.
\end{enumerate}

Let $X$ be a complete variety, $Y$ any scheme and $L$ a line bundle on
$X\times Y$. There exists a unique closed subscheme $Y_1\hookrightarrow Y$
such that:
\begin{enumerate}
\item if $L_1$ is the restriction of $L$ to $X\times Y_1$, then
there is a line bundle $M_1$ on $Y_1$ and an isomorphism
$p_2^*M_1\simeq L_1$;
\item if $f:Z\to Y$ and $p_2^*K\simeq(1_X\times f)^*L$ for a line bundle
$K$ on $Z$, then $f$ factors through $Y_1$.
\end{enumerate}

Let $Q$ be a line bundle on $X\times Y$, with trivial restrictions to the
two coordinate factors, and $\dim X=\dim Y$. The following are equivalent:
\begin{enumerate}
\item no nonzero subscheme of $X$ makes $Q$ trivial;
\item no nonzero subscheme of $Y$ makes $Q$ trivial;
\item $|\chi(Q)|=1$.
\end{enumerate}
When they hold, $Y\simeq\widehat X$ and $X\simeq\widehat Y$.

For every $a\in X$, the translation $T_a(x)=a+x$ is an automorphism of $X$;
its inverse is $T_{-a}$.  Consequently, local geometric properties are
preserved by translation.

Let $D$ be an effective divisor on $X$, $L=\mathcal O_X(D)$, and
$H=\{x:T_x^*D=D\}$.  The following are equivalent:
\begin{enumerate}
\item $H$ is finite;
\item $K(L)$ is finite;
\item $|2D|$ is base-point free and defines a finite morphism
      $X\to\mathbf P^N$;
\item $L$ is ample.
\end{enumerate}

For $L=L(H,\alpha)$ on $X=V/U$, the following are equivalent:
\begin{enumerate}
\item for every complex subtorus $Y$ there are $N>0$, a section $\sigma$ of
  $L^N$, and $x_1,x_2$ with $x_1-x_2\in Y$, $\sigma(x_1)=0$ and
  $\sigma(x_2)\ne0$;
\item $H$ is positive definite;
\item the sections of $L^n$ embed $X$ as a closed complex submanifold of a
  projective space for every $n\ge3$.
\end{enumerate}

For every projective variety $X/K$ and $L\in{\rm Pic}X$, there is a height
$h_L$ on $X(\overline K)$, unique up to equivalence, such that
\begin{enumerate}
\item $h_{L_1\otimes L_2}\sim h_{L_1}+h_{L_2}$;
\item for $X=\mathbb P^n$, $h_{\mathcal O(1)}$ is the projective height;
\item for $\varphi:X\to Y$, $h_{\varphi^*L}\sim h_L\circ\varphi$.
\end{enumerate}
